'use strict';

// The national station table: CRS -> { name, lat, lon }. Generated by map-service/scripts/build-stations.js
// from the `uk-railway-stations` dataset (ODbL), committed at map-service/data/stations.json, and only
// ever READ here.

const fs = require('fs');
const path = require('path');

const DEFAULT_STATIONS_FILE = path.resolve(__dirname, '..', '..', 'data', 'stations.json');

const finite = v => typeof v === 'number' && Number.isFinite(v);

/**
 * Load the table. Accepts the generated shape ({ _source, ..., stations: { CRS: {...} } }) or a bare
 * { CRS: {...} } map. An entry that is not a three-letter CRS with a numeric, in-range lat and lon is
 * skipped and counted, so a damaged file shows up as `skipped` rather than as silently missing stations.
 * @returns {{ byCrs: Map<string,{name:string,lat:number,lon:number}>, count: number, skipped: number, source: string|null, file: string }}
 */
function loadStations(file = DEFAULT_STATIONS_FILE) {
  let text;
  try { text = fs.readFileSync(file, 'utf8'); }
  catch (e) {
    const err = new Error(`Cannot read the station table ${file} (${e.code || e.message}). It is generated by map-service/scripts/build-stations.js; pass --stations to use another file.`);
    err.code = 'STATIONS_UNREADABLE';
    throw err;
  }
  let doc;
  try { doc = JSON.parse(text); }
  catch (e) {
    const err = new Error(`The station table ${file} is not valid JSON (${e.message}). Regenerate it with map-service/scripts/build-stations.js.`);
    err.code = 'STATIONS_INVALID';
    throw err;
  }
  const table = doc && typeof doc === 'object' && doc.stations && typeof doc.stations === 'object' ? doc.stations : doc;

  const byCrs = new Map();
  let skipped = 0;
  for (const [crs, s] of Object.entries(table || {})) {
    if (crs.startsWith('_')) continue;                                    // _source, _licence, ...
    const ok = /^[A-Z]{3}$/.test(crs) && s && finite(s.lat) && finite(s.lon)
      && s.lat >= -90 && s.lat <= 90 && s.lon >= -180 && s.lon <= 180;
    if (!ok) { skipped++; continue; }
    byCrs.set(crs, { name: typeof s.name === 'string' && s.name ? s.name : crs, lat: s.lat, lon: s.lon });
  }
  if (byCrs.size === 0) {
    const err = new Error(`The station table ${file} has no usable stations. Regenerate it with map-service/scripts/build-stations.js.`);
    err.code = 'STATIONS_EMPTY';
    throw err;
  }
  return { byCrs, count: byCrs.size, skipped, source: typeof doc._source === 'string' ? doc._source : null, file };
}

module.exports = { loadStations, DEFAULT_STATIONS_FILE };
